#!/usr/bin/env python3
"""Overdue fee statements: python3 fees.py INPUT_DIR OUTPUT_FILE"""
import configparser
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]


def cents(s):
    return int((Decimal(s.strip()) * 100).to_integral_value())


def pnum(s):
    return int(re.sub(r"\D", "", s) or 0)


def pdate(s):
    return date.fromisoformat(s.strip())


def parse_offset(s):
    s = s.strip()
    sign = -1 if s.startswith("-") else 1
    h, m = s.lstrip("+-").split(":")
    return sign * (int(h) * 60 + int(m))


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        rows = list(csv.DictReader(f))
    return [{(k or "").strip(): (v or "").strip() for k, v in r.items()} for r in rows]


def main(indir, outfile):
    cp = configparser.ConfigParser(interpolation=None, inline_comment_prefixes=None)
    cp.optionxform = str
    with open(os.path.join(indir, "policy.ini"), encoding="utf-8-sig") as f:
        cp.read_file(f)
    lib = cp["statement"]["library"].strip()
    pstart = pdate(cp["statement"]["period_start"])
    pend = pdate(cp["statement"]["period_end"])
    clk = cp["clock"] if cp.has_section("clock") else {}
    base_off = parse_offset(clk.get("offset", "+00:00"))
    changes = []
    for part in (clk.get("changes", "") or "").split(";"):
        part = part.strip()
        if part:
            inst, off = part.split()
            changes.append((datetime.strptime(inst, "%Y-%m-%dT%H:%MZ").replace(tzinfo=timezone.utc),
                            parse_offset(off)))
    changes.sort()

    items = {}
    cats = {}
    for sec in cp.sections():
        if sec.lower().startswith("item:"):
            s = cp[sec]
            items[sec[5:].strip().lower()] = dict(
                name=sec[5:].strip(), loan_days=int(s["loan_days"]), renewals=int(s["renewals"]),
                grace=int(s["grace_days"]), daily=cents(s["daily"]), loan_cap=cents(s["loan_cap"]))
        elif sec.lower().startswith("category:"):
            s = cp[sec]
            cap = s["statement_cap"].strip()
            cats[sec[9:].strip().lower()] = dict(
                name=sec[9:].strip(), cap=None if cap.lower() == "none" else cents(cap),
                discount=int(s["discount"]),
                exempt={x.strip().lower() for x in s.get("exempt", "").split(",") if x.strip()})

    branches = read_csv(os.path.join(indir, "branches.csv"))
    open_days = {b["branch"].upper(): {d.lower() for d in b["open_days"].split()} for b in branches}
    cal = {}
    for r in read_csv(os.path.join(indir, "calendar.csv")):
        d = r["date"]
        if ".." in d:
            a, b = d.split("..")
        else:
            a = b = d
        cal.setdefault(r["branch"].upper(), []).append((pdate(a), pdate(b), r["status"].lower()))

    def status(rows, d):
        for a, b, st in rows:
            if a <= d <= b:
                return st
        return None

    open_cache = {}

    def is_open(br, d):
        k = (br, d)
        if k not in open_cache:
            st = status(cal.get(br, []), d)
            if st is None:
                st = status(cal.get("*", []), d)
            if st is None:
                open_cache[k] = DAYS[d.weekday()].lower() in open_days.get(br, set())
            else:
                open_cache[k] = st == "open"
        return open_cache[k]

    def next_open(br, d):
        while not is_open(br, d):
            d += timedelta(days=1)
        return d

    patrons = {}
    for r in read_csv(os.path.join(indir, "patrons.csv")):
        patrons.setdefault(pnum(r["patron"]), []).append((pdate(r["since"]), r["patron"], r["category"]))
    for v in patrons.values():
        v.sort(key=lambda x: x[0])

    def category(pn, d):
        best = None
        for since, _, c in patrons[pn]:
            if since <= d:
                best = c
        if best is None:
            best = patrons[pn][0][2]
        return cats[best.lower()]

    waivers = []
    for r in read_csv(os.path.join(indir, "waivers.csv")):
        if r["status"].lower() != "active":
            continue
        v = r["value"].strip()
        waivers.append((pnum(r["patron"]), r["loan"], None if v.lower() == "full" else cents(v)))

    # events
    def local(ev):
        if "time" in ev and ev["time"]:
            return datetime.strptime(ev["time"].strip(), "%Y-%m-%d %H:%M")
        at = ev["at"].strip().replace("Z", "+00:00")
        dt = datetime.fromisoformat(at)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        dt = dt.astimezone(timezone.utc)
        off = base_off
        for inst, o in changes:
            if inst <= dt:
                off = o
        return dt.replace(tzinfo=None) + timedelta(minutes=off)

    events = {}
    exdir = os.path.join(indir, "exports")
    for fn in sorted(os.listdir(exdir)):
        if not (fn.endswith(".csv") or fn.endswith(".jsonl")):
            continue
        path = os.path.join(exdir, fn)
        if fn.endswith(".csv"):
            recs = read_csv(path)
        else:
            recs = []
            with open(path, encoding="utf-8-sig") as f:
                for line in f:
                    if line.strip():
                        recs.append(json.loads(line))
        for ev in recs:
            eid = str(ev.get("event", "")).strip()
            if eid and eid not in events:
                events[eid] = ev

    cancelled = set()
    for ev in events.values():
        if ev.get("type", "").strip().lower() == "void" and ev.get("target"):
            cancelled.add(ev["target"].strip())

    loans = {}
    later = {}
    for eid, ev in events.items():
        t = ev.get("type", "").strip().lower()
        if t == "void" or eid in cancelled:
            continue
        lt = local(ev)
        lid = str(ev.get("loan", "")).strip()
        if t == "checkout":
            loans[lid] = dict(id=lid, patron=pnum(ev["patron"]), item=ev.get("item", ""),
                              type=ev["item_type"].strip().lower(), branch=ev["branch"].strip().upper(),
                              out=lt.date())
        elif t in ("renew", "return"):
            later.setdefault(lid, []).append((lt, t, (ev.get("via") or "").strip().lower()))

    rows = []
    for lid, L in loans.items():
        if L["out"] > pend:
            continue
        it = items[L["type"]]
        br = L["branch"]
        due = next_open(br, L["out"] + timedelta(days=it["loan_days"]))
        nren = 0
        ret = None
        for lt, t, via in sorted(later.get(lid, []), key=lambda x: x[0]):
            d = lt.date()
            if t == "renew":
                if d <= due and nren < it["renewals"] and d <= pend:
                    nren += 1
                    due = next_open(br, d + timedelta(days=it["loan_days"]))
            else:
                ret = d - timedelta(days=1) if via == "dropbox" else d
                break
        if ret is not None and ret > pend:
            ret = None
        if ret is not None and ret < pstart:
            continue
        end = ret if ret is not None else pend
        od = 0
        d = due + timedelta(days=1)
        while d <= end:
            if is_open(br, d):
                od += 1
            d += timedelta(days=1)
        if od == 0:
            continue
        charged = 0 if od <= it["grace"] else od - it["grace"]  # CIRC-4418
        cat = category(L["patron"], L["out"])
        fee = charged * it["daily"]
        if L["type"] in cat["exempt"]:
            fee = 0
        fee = min(fee, it["loan_cap"])
        fee = (fee * (100 - cat["discount"]) + 50) // 100
        waived = 0
        full = False
        tot = 0
        for wp, wl, wv in waivers:
            if wp == L["patron"] and (wl == "*" or wl == lid):
                if wv is None:
                    full = True
                else:
                    tot += wv
        waived = fee if full else min(tot, fee)
        rows.append(dict(L=L, due=due, ret=ret, od=od, charged=charged, assessed=fee, waived=waived,
                         net=fee - waived, capped=0))

    by_patron = {}
    for r in rows:
        by_patron.setdefault(r["L"]["patron"], []).append(r)
    statements = []
    for pn in sorted(by_patron):
        rs = by_patron[pn]
        cat = category(pn, pend)
        if cat["cap"] is not None:
            excess = sum(r["net"] for r in rs) - cat["cap"]
            if excess > 0:
                for r in sorted(rs, key=lambda r: (r["due"], r["L"]["id"]), reverse=True):
                    take = min(excess, r["net"])
                    r["capped"] = take
                    excess -= take
                    if excess <= 0:
                        break
        rs.sort(key=lambda r: (r["due"], r["L"]["id"]))
        out_loans = []
        for r in rs:
            L = r["L"]
            out_loans.append({
                "loan": L["id"], "item": L["item"], "item_type": items[L["type"]]["name"],
                "branch": L["branch"], "checkout": L["out"].isoformat(), "due": r["due"].isoformat(),
                "returned": r["ret"].isoformat() if r["ret"] else None,
                "overdue_days": r["od"], "charged_days": r["charged"], "assessed": r["assessed"],
                "waived": r["waived"], "capped": r["capped"], "billed": r["net"] - r["capped"]})
        st = {"patron": patrons[pn][0][1], "category": cat["name"], "loans": out_loans}
        for k in ("assessed", "waived", "capped", "billed"):
            st[k] = sum(l[k] for l in out_loans)
        statements.append(st)

    bsum = []
    for b in branches:
        bid = b["branch"]
        ls = [l for s in statements for l in s["loans"] if l["branch"] == bid.upper()]
        e = {"branch": bid, "loans": len(ls), "charged_days": sum(l["charged_days"] for l in ls)}
        for k in ("assessed", "waived", "capped", "billed"):
            e[k] = sum(l[k] for l in ls)
        bsum.append(e)

    res = {"library": lib, "period": {"start": pstart.isoformat(), "end": pend.isoformat()},
           "statements": statements, "branches": bsum}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
